xql_query:
// ============================================================
// Rule: CTX_Deno JavaScript Execution from AppData or Temp Directory
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Deno JavaScript Execution from AppData or Temp Directory.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059.007 - Command and Scripting Interpreter: JavaScript

// Title: CTX - Deno JavaScript Execution from AppData or Temp Directory
// Description: Detecta Deno executando arquivos JavaScript/TypeScript localizados em AppData/Roaming/Temp.
// Esse comportamento pode indicar payload baixado e armazenado em diretório de usuário para execução local.
// MITRE ATT&CK: T1059.007 (JavaScript), T1036 (Masquerading)
//
// NOTA TH: Esta regra complementa CTX_GEN_002 (execução remota). Aqui o foco é payload local — o script
// já foi baixado e está em TEMP/AppData, pronto para execução ou persistência.
// Cenário típico: stage 1 dropper baixa .js para %TEMP%, executa com deno.exe --allow-all.
// Overlap intencional com CTX_GEN_002: se ambos dispararem no mesmo host, elevar a prioridade do caso.
//
// CORREÇÃO [v2]: Removido explorer.exe e conhost.exe da lista de parents válidos.
// explorer.exe chamando deno.exe de TEMP é igualmente suspeito e não deve ser excluído.
// conhost.exe não spawna processos diretamente — aparece como intermediário de console, não como pai real.
// actor_cmd adicionado ao filtro de parent suspeito para cobertura de scripts ofuscados.

config case_sensitive = false
| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START

| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_process_image_name,
    action_process_image_path,
    action_process_image_command_line,
    action_process_image_sha256,
    causality_actor_process_image_name,
    causality_actor_process_command_line

| alter action_cmd = lowercase(action_process_image_command_line)
| alter actor_cmd = lowercase(actor_process_command_line)

// Filtro 1: processo é deno.exe
| filter action_process_image_name = "deno.exe"

// Filtro 2: script .js ou .ts em diretório de usuário
| filter action_cmd ~= "\\.(js|mjs|ts)"
| filter action_cmd ~= "(\\\\appdata\\\\roaming\\\\|\\\\appdata\\\\local\\\\temp\\\\|%temp%|\\\\temp\\\\)"

// Filtro 3: execução com permissões amplas (qualquer flag de permissão é suspeita neste contexto)
| filter action_cmd ~= "(^|\\s)--allow-all(\\s|$)"
    or action_cmd ~= "(^|\\s)-[aA](\\s|$)"
    or action_cmd ~= "(--allow-read|--allow-run|--allow-net|--allow-write)"

// Filtro 4: parent process suspeito — scripting engines e shells são os vetores mais comuns
// Nota: explorer.exe foi removido — Deno de TEMP via explorer é igualmente anômalo
| filter actor_process_image_name in ("powershell.exe", "pwsh.exe", "cmd.exe", "wscript.exe", "cscript.exe")

| sort desc _time
